import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CxcmDv9y.js";var i=JSON.parse(`{"title":"Config","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md","lastUpdated":1792111269000}`),a={name:`reference/config.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to “Config”">​</a></h1><p>Turna configuration is decoded into four main sections: <code>loads</code>, <code>preprocess</code>, <code>server</code>, and <code>services</code>.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">log_level</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">info</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">print</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">&quot;turna started for {{ .APP_NAME }}&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">loads</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: []</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">env</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: {}</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">env_values</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: []</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">preprocess</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: []</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">server</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: {}</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">services</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: []</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">telemetry</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: {}</span></span></code></pre></div><h2 id="startup-order" tabindex="-1">Startup Order <a class="header-anchor" href="#startup-order" aria-label="Permalink to “Startup Order”">​</a></h2><p>Turna applies configuration and runtime work in this order:</p><ol><li>Load bootstrap settings from environment variables.</li><li>Load Turna application config from the <a href="#application-config-sources">application config sources</a>: Consul, AWS, Azure, Vault, GCP, HTTP, file, and environment.</li><li>Run <code>loads</code> and store loaded data in template memory.</li><li>Apply top-level <code>env_values</code> and <code>env</code> to Turna&#39;s own process environment, then refresh the default HTTP transport&#39;s proxy settings.</li><li>Run <code>preprocess</code> modules.</li><li>Render and write the top-level <code>print</code> message to logs when configured.</li><li>Initialize telemetry and start server entrypoints and routers.</li><li>Start services.</li></ol><p>Dynamic <code>loads</code> can update loaded data later. When that happens, Turna refreshes template data and service filters.</p><h2 id="top-level-fields" tabindex="-1">Top-Level Fields <a class="header-anchor" href="#top-level-fields" aria-label="Permalink to “Top-Level Fields”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>log_level</code></td><td>string</td><td>Application log level. Default is <code>info</code>.</td></tr><tr><td><code>print</code></td><td>string</td><td>Template rendered after loads and preprocess complete.</td></tr><tr><td><code>loads</code></td><td>array</td><td>External data loaders. See <a href="./loads.html">Loads</a>.</td></tr><tr><td><code>env</code></td><td>object</td><td>Set or overwrite Turna&#39;s process environment after loads. Values support templates.</td></tr><tr><td><code>env_values</code></td><td>array</td><td><code>/</code>-separated paths to maps in loaded data to export as process environment. Later paths override earlier ones; <code>env</code> has final precedence. Missing or non-map paths fail startup.</td></tr><tr><td><code>preprocess</code></td><td>array</td><td>Pre-start file processors. See <a href="./preprocess/preprocess.html">Preprocess</a>.</td></tr><tr><td><code>server</code></td><td>object</td><td>HTTP/TCP server configuration. See <a href="./server/server.html">Server</a>.</td></tr><tr><td><code>services</code></td><td>array</td><td>Local commands to run. See <a href="./services.html">Services</a>.</td></tr><tr><td><code>telemetry</code></td><td>object</td><td>OpenTelemetry exporter settings. See <a href="#telemetry">Telemetry</a>.</td></tr></tbody></table><p>The debug <code>loaded config</code> log respects <code>log:&quot;-&quot;</code> struct tags: tagged fields are omitted, while other fields keep their <code>cfg</code> names. This does not affect configuration decoding. Process/service environment maps, inline loader content, credentials, private keys and marked authentication fields are excluded. This is not a general string scrubber: avoid putting secrets in unmarked fields such as commands or URLs, or in explicit <code>print</code> templates.</p><h2 id="process-environment" tabindex="-1">Process Environment <a class="header-anchor" href="#process-environment" aria-label="Permalink to “Process Environment”">​</a></h2><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">loads</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">  - </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">name</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">settings</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    statics</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">      - </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">content</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          content</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#A0A0A0;--shiki-dark:#A0A0A0;">|</span></span>
<span class="line"><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">            environment:</span></span>
<span class="line"><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">              OTEL_SERVICE_NAME: turna-proxy</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">env_values</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">  - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">settings/environment</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">env</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  HTTPS_PROXY</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">http://proxy.internal:8080</span></span></code></pre></div><p>These settings add or overwrite variables in Turna itself, not just child services. Unspecified variables are preserved; an empty value sets an empty variable rather than removing it. Values are rendered and validated before environment changes are applied. Templates see the environment from before this step, so do not rely on one entry referencing another via <code>env</code>.</p><p>This runs once at startup. Dynamic loads do not reapply environment settings. It does not re-decode already-loaded application config, reinitialize clients, or change the parent shell. Child services inherit these variables according to their <code>inherit_env</code> setting and can override them with their own <code>env</code>.</p><p>Only components that read the environment after this step observe the new values. In particular, <code>gcp_token</code> reads credentials, certificates and audience from its middleware config, not automatically from environment variables; setting a GCP environment variable does not replace those fields or invalidate cached tokens.</p><p>After applying environment settings, Turna replaces the default HTTP transport with a clone whose proxy function reads a fresh snapshot of <code>HTTP_PROXY</code>, <code>HTTPS_PROXY</code> and <code>NO_PROXY</code> (and their lowercase equivalents). This bypasses Go&#39;s process-wide proxy environment cache, even if loads already made HTTP requests. Middleware clients that subsequently use or clone the default transport, including <code>gcp_token</code>, use the new proxy settings. Existing clients with their own transports and clients with explicit proxy settings are unaffected. The proxy snapshot is not refreshed on dynamic reload.</p><h2 id="telemetry" tabindex="-1">Telemetry <a class="header-anchor" href="#telemetry" aria-label="Permalink to “Telemetry”">​</a></h2><p><code>telemetry</code> configures the global OpenTelemetry meter and tracer providers with <a href="https://github.com/rakunlabs/tell" target="_blank" rel="noreferrer"><code>github.com/rakunlabs/tell</code></a>. Metrics and traces are exported over OTLP/gRPC. Without a collector address (and without <code>OTEL_EXPORTER_OTLP_ENDPOINT</code>) the providers are noop, so the telemetry middlewares cost almost nothing.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">telemetry</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  collector</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">otel-collector:4317</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  server_name</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  tls</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    enabled</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">false</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    insecure_skip_verify</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">false</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    cert_file</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    key_file</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    ca_file</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  metric</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    disabled</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">false</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    default</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      go_runtime</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">true</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  trace</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    disabled</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">false</span></span></code></pre></div><p>Telemetry is recorded by the <code>telemetry</code> middlewares of <a href="./server/http/middlewares/telemetry.html">HTTP</a>, <a href="./server/tcp/middlewares/telemetry.html">TCP</a> and <a href="./server/udp/middlewares/telemetry.html">UDP</a>. Service name and resource attributes follow the standard <code>OTEL_SERVICE_NAME</code> and <code>OTEL_RESOURCE_ATTRIBUTES</code> environment variables.</p><h2 id="application-config-sources" tabindex="-1">Application Config Sources <a class="header-anchor" href="#application-config-sources" aria-label="Permalink to “Application Config Sources”">​</a></h2><p>Turna&#39;s own configuration (everything on this page) is loaded with <a href="https://github.com/rakunlabs/chu" target="_blank" rel="noreferrer"><code>github.com/rakunlabs/chu</code></a>. Every source looks up a document named after the application, <code>turna</code> by default, and later sources override earlier ones:</p><table tabindex="0"><thead><tr><th>Order</th><th>Source</th><th>Enabled when</th><th>Document looked up</th></tr></thead><tbody><tr><td>1</td><td><code>default</code></td><td>always</td><td><code>default</code> struct tags</td></tr><tr><td>2</td><td><code>consul</code></td><td><code>CONSUL_HTTP_ADDR</code> is set</td><td>KV key <code>&lt;CONSUL_CONFIG_PATH_PREFIX&gt;/turna</code></td></tr><tr><td>3</td><td><code>awsssm</code></td><td><code>AWS_REGION</code> or <code>AWS_DEFAULT_REGION</code> is set</td><td>parameter <code>/&lt;AWS_SSM_PREFIX&gt;/turna</code></td></tr><tr><td>4</td><td><code>awssecrets</code></td><td><code>AWS_REGION</code> or <code>AWS_DEFAULT_REGION</code> is set</td><td>secret <code>&lt;AWS_SECRETS_PREFIX&gt;/turna</code></td></tr><tr><td>5</td><td><code>azurekeyvault</code></td><td><code>AZURE_KEYVAULT_URL</code> or <code>AZURE_KEYVAULT_NAME</code> is set</td><td>secret <code>turna</code></td></tr><tr><td>6</td><td><code>vault</code></td><td><code>VAULT_ADDR</code> or <code>VAULT_AGENT_ADDR</code> is set</td><td>KVv2 <code>&lt;VAULT_SECRET_BASE_PATH&gt;/turna</code></td></tr><tr><td>7</td><td><code>gcpparameter</code></td><td><code>GCP_PROJECT_ID</code> is set</td><td>parameter <code>turna</code></td></tr><tr><td>8</td><td><code>gcpsecret</code></td><td><code>GCP_PROJECT_ID</code> is set</td><td>secret <code>turna</code></td></tr><tr><td>9</td><td><code>http</code></td><td><code>CONFIG_HTTP_ADDR</code> is set</td><td><code>GET &lt;CONFIG_HTTP_ADDR&gt;/turna&lt;CONFIG_HTTP_SUFFIX&gt;</code></td></tr><tr><td>10</td><td><code>file</code></td><td>always</td><td><code>turna.toml</code>, <code>.yaml</code>, <code>.yml</code> or <code>.json</code></td></tr><tr><td>11</td><td><code>env</code></td><td>always</td><td>environment variables and <code>.env</code> files</td></tr></tbody></table><p>A source whose address variable is missing, or whose document does not exist, is skipped. Any other error, such as failed authentication, stops startup.</p><p>Remote documents are decoded as YAML, so JSON works as well.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#8B8B8B94;--shiki-dark:#8B8B8B94;"># Base config in Consul, secrets from GCP Secret Manager, overrides from env</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">CONSUL_HTTP_ADDR</span><span style="--shiki-light:#A0A0A0;--shiki-dark:#A0A0A0;">=</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">consul:8500</span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;"> \\</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">CONSUL_CONFIG_PATH_PREFIX=finops </span><span style="--shiki-light:#A0A0A0;--shiki-dark:#A0A0A0;">\\</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">GCP_PROJECT_ID=my-project </span><span style="--shiki-light:#A0A0A0;--shiki-dark:#A0A0A0;">\\</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">LOG_LEVEL=debug </span><span style="--shiki-light:#A0A0A0;--shiki-dark:#A0A0A0;">\\</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">turna</span></span></code></pre></div><h3 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to “Naming”">​</a></h3><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>APP_NAME</code></td><td>Document name used by every source. Default is <code>turna</code>.</td></tr><tr><td><code>CONFIG_NAME_PREFIX</code></td><td>Prepended to the name as <code>&lt;prefix&gt;/&lt;APP_NAME&gt;</code>.</td></tr><tr><td><code>CONFIG_SET_&lt;SOURCE&gt;</code></td><td>Set to <code>false</code> to skip a source, for example <code>CONFIG_SET_VAULT=false</code> or <code>CONFIG_SET_GCPSECRET=false</code>. Useful when a backend is down and should not block startup.</td></tr></tbody></table><h3 id="file" tabindex="-1">File <a class="header-anchor" href="#file" aria-label="Permalink to “File”">​</a></h3><p>Turna looks for <code>turna.toml</code>, <code>turna.yaml</code>, <code>turna.yml</code> or <code>turna.json</code> in the current directory, then in <code>/etc</code>. <code>CONFIG_FILE_TURNA</code> (the uppercased app name) or <code>CONFIG_FILE</code> points to a specific file instead.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">CONFIG_FILE</span><span style="--shiki-light:#A0A0A0;--shiki-dark:#A0A0A0;">=</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">local.yaml</span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;"> turna</span></span></code></pre></div><h3 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to “Environment”">​</a></h3><p>Environment variables are loaded last and override every other source. Field paths are uppercased and joined with <code>_</code>, so <code>log_level</code> is <code>LOG_LEVEL</code> and <code>telemetry.collector</code> is <code>TELEMETRY_COLLECTOR</code>. <code>.env</code> and <code>.env.local</code> in the current directory are read automatically; <code>CONFIG_ENV_FILE</code> adds one more file.</p><h3 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to “HTTP”">​</a></h3><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>CONFIG_HTTP_ADDR</code></td><td>Base URL. The app name is appended as a path.</td></tr><tr><td><code>CONFIG_HTTP_SUFFIX</code></td><td>Appended after the name, for example <code>.yaml</code>.</td></tr><tr><td><code>CONFIG_HTTP_QUERY</code></td><td>Query string added to the request, for example <code>env=prod</code>.</td></tr></tbody></table><p>Only a <code>200</code> response is used; <code>204</code> and <code>404</code> skip the source.</p><h3 id="consul" tabindex="-1">Consul <a class="header-anchor" href="#consul" aria-label="Permalink to “Consul”">​</a></h3><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>CONSUL_HTTP_ADDR</code></td><td>Consul address. Required to enable the source.</td></tr><tr><td><code>CONSUL_CONFIG_PATH_PREFIX</code></td><td>Key prefix, the key becomes <code>&lt;prefix&gt;/turna</code>.</td></tr></tbody></table><p>The client also reads the standard <code>github.com/hashicorp/consul/api</code> variables:</p><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>CONSUL_HTTP_TOKEN_FILE</code></td><td>File containing the Consul token.</td></tr><tr><td><code>CONSUL_HTTP_TOKEN</code></td><td>Consul token.</td></tr><tr><td><code>CONSUL_HTTP_AUTH</code></td><td>HTTP basic auth.</td></tr><tr><td><code>CONSUL_HTTP_SSL</code></td><td>Enable TLS.</td></tr><tr><td><code>CONSUL_TLS_SERVER_NAME</code></td><td>TLS server name.</td></tr><tr><td><code>CONSUL_CACERT</code></td><td>CA certificate file.</td></tr><tr><td><code>CONSUL_CAPATH</code></td><td>CA certificate directory.</td></tr><tr><td><code>CONSUL_CLIENT_CERT</code></td><td>Client certificate.</td></tr><tr><td><code>CONSUL_CLIENT_KEY</code></td><td>Client key.</td></tr><tr><td><code>CONSUL_HTTP_SSL_VERIFY</code></td><td>TLS verification toggle.</td></tr><tr><td><code>CONSUL_NAMESPACE</code></td><td>Consul namespace.</td></tr><tr><td><code>CONSUL_PARTITION</code></td><td>Consul partition.</td></tr></tbody></table><h3 id="vault" tabindex="-1">Vault <a class="header-anchor" href="#vault" aria-label="Permalink to “Vault”">​</a></h3><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>VAULT_ADDR</code>, <code>VAULT_AGENT_ADDR</code></td><td>Vault address. Required to enable the source.</td></tr><tr><td><code>VAULT_SECRET_BASE_PATH</code></td><td>KVv2 mount path. Required when Vault is enabled.</td></tr><tr><td><code>VAULT_ROLE_ID</code></td><td>AppRole role ID. When set, Turna logs in with AppRole; otherwise <code>VAULT_TOKEN</code> is used.</td></tr><tr><td><code>VAULT_ROLE_SECRET</code></td><td>AppRole secret ID.</td></tr><tr><td><code>VAULT_APPROLE_BASE_PATH</code></td><td>AppRole login path. Default is <code>auth/approle/login</code>.</td></tr></tbody></table><p>The client also reads the standard <code>github.com/hashicorp/vault/api</code> variables:</p><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>VAULT_TOKEN</code></td><td>Vault token.</td></tr><tr><td><code>VAULT_MAX_RETRIES</code></td><td>Retry count.</td></tr><tr><td><code>VAULT_CACERT</code></td><td>CA certificate file.</td></tr><tr><td><code>VAULT_CACERT_BYTES</code></td><td>CA certificate bytes.</td></tr><tr><td><code>VAULT_CAPATH</code></td><td>CA certificate directory.</td></tr><tr><td><code>VAULT_CLIENT_CERT</code></td><td>Client certificate.</td></tr><tr><td><code>VAULT_CLIENT_KEY</code></td><td>Client key.</td></tr><tr><td><code>VAULT_RATE_LIMIT</code></td><td>Client-side rate limit.</td></tr><tr><td><code>VAULT_CLIENT_TIMEOUT</code></td><td>Client timeout.</td></tr><tr><td><code>VAULT_SKIP_VERIFY</code></td><td>Skip TLS verification.</td></tr><tr><td><code>VAULT_TLS_SERVER_NAME</code></td><td>TLS server name.</td></tr><tr><td><code>VAULT_HTTP_PROXY</code></td><td>HTTP proxy.</td></tr><tr><td><code>VAULT_PROXY_ADDR</code></td><td>Proxy address.</td></tr><tr><td><code>VAULT_DISABLE_REDIRECTS</code></td><td>Disable redirects.</td></tr></tbody></table><h3 id="aws" tabindex="-1">AWS <a class="header-anchor" href="#aws" aria-label="Permalink to “AWS”">​</a></h3><p>Both AWS sources use the default AWS credential chain (environment, shared config, IAM role).</p><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>AWS_REGION</code>, <code>AWS_DEFAULT_REGION</code></td><td>Region. Required to enable the sources.</td></tr><tr><td><code>AWS_SSM_PREFIX</code></td><td>Parameter Store prefix, the name becomes <code>/&lt;prefix&gt;/turna</code>. Loaded with decryption.</td></tr><tr><td><code>AWS_SECRETS_PREFIX</code></td><td>Secrets Manager prefix, the secret id becomes <code>&lt;prefix&gt;/turna</code>.</td></tr></tbody></table><h3 id="azure-key-vault" tabindex="-1">Azure Key Vault <a class="header-anchor" href="#azure-key-vault" aria-label="Permalink to “Azure Key Vault”">​</a></h3><p>Uses <code>DefaultAzureCredential</code> (environment, managed identity, Azure CLI). The latest version of the secret is loaded; <code>/</code> in the name is replaced with <code>-</code>.</p><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>AZURE_KEYVAULT_URL</code></td><td>Vault URL, for example <code>https://my-vault.vault.azure.net/</code>.</td></tr><tr><td><code>AZURE_KEYVAULT_NAME</code></td><td>Vault name, used to build the URL when <code>AZURE_KEYVAULT_URL</code> is unset.</td></tr></tbody></table><h3 id="gcp" tabindex="-1">GCP <a class="header-anchor" href="#gcp" aria-label="Permalink to “GCP”">​</a></h3><p>Both GCP sources use Application Default Credentials (<code>GOOGLE_APPLICATION_CREDENTIALS</code>, workload identity). <code>/</code> in the name is replaced with <code>-</code>.</p><table tabindex="0"><thead><tr><th>Environment variable</th><th>Description</th></tr></thead><tbody><tr><td><code>GCP_PROJECT_ID</code></td><td>Project id. Required to enable the sources.</td></tr><tr><td><code>GCP_PARAMETER_LOCATION</code></td><td>Parameter Manager location. Default is <code>global</code>.</td></tr><tr><td><code>GCP_PARAMETER_VERSION</code></td><td>Parameter version to render. Default is <code>latest</code>. Referenced secrets are resolved server-side.</td></tr><tr><td><code>GCP_PARAMETER_FALLBACK</code></td><td>When <code>true</code> and <code>latest</code> is disabled, use the most recent enabled version.</td></tr><tr><td><code>GCP_SECRET_LOCATION</code></td><td>Secret Manager location. Default is <code>global</code>.</td></tr><tr><td><code>GCP_SECRET_VERSION</code></td><td>Secret version. Default is <code>latest</code>.</td></tr><tr><td><code>GCP_SECRET_ADDITIONAL</code></td><td>Comma-separated shared secrets loaded before <code>turna</code>, for example <code>generic,keycloak</code>. Missing ones are skipped.</td></tr></tbody></table>`,53)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};